import json
import numpy as np
import shutil
import pandas as pd
from pathlib import Path
from scipy.interpolate import PchipInterpolator



# --- 1. GET CONTINUOUS CONTOUR --- (Will allow us to set dX manually later)
def getCurrentContour(N):

    #Get raw contour data from CSV file generated by contour code3
    contour_file = Path(__file__).parent / "current_contour.csv"
    data = pd.read_csv(contour_file)
    z_raw = data["Z_Coordinate_in"].to_numpy()
    r_raw = data["R_Coordinate_in"].to_numpy()

    #Get chamber length
    geometry_params = getCurrentEngineParameters()
    L_ch = geometry_params["L_ch"] #first get chamber length

    #Add on Chamber Length to contour 

    z_contraction_start = z_raw[0]
    r_c = r_raw[0]

    # Just need enough points to define the straight chamber
    z_chamber = np.array([z_contraction_start - L_ch, z_contraction_start])
    r_chamber = np.array([r_c, r_c])

    # Avoid duplicating the contraction-start point
    z_full_contour = np.concatenate((z_chamber[:-1], z_raw))
    r_full_contour = np.concatenate((r_chamber[:-1],r_raw))

    #Convert to SI
    z_full_contour *= 0.0254
    r_full_contour *= 0.0254

    interpContour = PchipInterpolator(z_full_contour, r_full_contour)

    #Build new arrays for contour axial + radial positions based on specified step size
    z = np.linspace(z_full_contour[0], z_full_contour[-1], N)
    r = interpContour(z)

    #Compute area at each point
    A = np.pi*r**2

    #Get throat index
    throat_index = np.argmin(r)

    #Calculate segment lengths between each points in contour
    #Will be useful for channel solver later
    ds = np.sqrt(np.diff(z)**2 + np.diff(r)**2)

    return {
        "N": N,
        "z": z,
        "r": r,
        "A": A,
        "throat_index": throat_index,
        "ds": ds,
    }

# --- 2. FUNCTION TO GET CURRENT ENGINE PARAMETERS ----
def getCurrentEngineParameters():
    parameter_file = Path(__file__).parent.parent / "Geometry" / "current_parameters.json"

    with open(parameter_file, "r") as file:
        geometry_params = json.load(file)

    return geometry_params


# --- 2. UPLOAD GEOMETRY TO DESIGN DATABASE --- (Manually Upload If Design Is Good)
# Save a copy of contour parameters JSON file to next Design # Folder
# Save a copy of Optimized Contour CSV file to next Design # Folder
def uploadToDesigns():

    geometry_dir = Path(__file__).parent
    designs_dir = geometry_dir / "Designs"

    # Find next design number
    design_numbers = [
        int(folder.name.replace("Design", ""))
        for folder in designs_dir.glob("Design*")
        if folder.is_dir()
    ]

    next_design = max(design_numbers, default=0) + 1

    # Create new design folder
    design_dir = designs_dir / f"Design{next_design}"
    design_dir.mkdir()

    # Copy current contour parameters
    shutil.copy(
        geometry_dir / "current_parameters.json",
        design_dir / "contour_parameters.json"
    )

    # Copy current optimized contour
    shutil.copy(
        geometry_dir / "current_contour.csv",
        design_dir / "optimized_contour.csv"
    )

    print(f"Design{next_design} saved to: {design_dir}")